    z_t63_t* boxed = (z_t63_t*)z_xmalloc(sizeof(z_t63_t));
    *boxed = z_t63_new(v);
    out.tag = Z_OPTION_STRING_TAG_SOME;
    out.data = boxed;
    return out;
